module TopModule (
    input clk,
    input reset,
    output reg [3:0] q
);

reg [3:0] count;
reg [3:0] next_count;

always @(posedge clk or posedge reset) begin
    if (reset) begin
        count <= 4'b0000;
    end else begin
        next_count <= count + 1'b1;
        if (next_count == 4'b1000) begin
            next_count <= 4'b0000;
        end
        q <= next_count;
    end
end

endmodule
